118	/// Append a line to %APPDATA%/DesktopPet/debug.log for field diagnostics.
119	fn dlog(msg: &str) {
120	    if let Some(path) = dirs::config_dir().map(|dir| dir.join("DesktopPet").join("debug.log")) {
121	        if let Some(parent) = path.parent() {
122	            let _ = std::fs::create_dir_all(parent);
123	        }
124	        if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
125	            use std::io::Write;
126	            let timestamp = std::time::SystemTime::now()
127	                .duration_since(std::time::UNIX_EPOCH)
128	                .map(|duration| duration.as_secs())
129	                .unwrap_or(0);
130	            let _ = writeln!(file, "[{timestamp}] {msg}");
131	        }
132	    }
