140	/// Report a pet window's opaque rectangle (physical px, window-relative) so
141	/// empty transparent areas of that overlay let clicks pass through to apps
142	/// below. Each pet window registers under its own label so multi-pet mode
143	/// doesn't have one window overwrite another's click-through rect.
144	#[tauri::command]
145	fn set_hit_rect(app: tauri::AppHandle, label: String, x: f64, y: f64, w: f64, h: f64) {
146	    if !is_pet_window(&label) {
147	        return;
148	    }
149	    if let Some(state) = app.try_state::<Mutex<HitRectMap>>() {
150	        if let Ok(mut m) = state.lock() {
151	            m.insert(label, HitRect { x, y, w, h });
152	        }
