468	        } else if let Some(w) = app.get_webview_window(FLOATING_BALL_LABEL) {
469	            let _ = w.show();
470	        }
471	    } else if let Some(w) = app.get_webview_window(FLOATING_BALL_LABEL) {
472	        let _ = w.hide();
473	    }
474	}
475	
105	  if (bmHint) bmHint.textContent = t("Shift-click to remove");
106	  input.placeholder = t("Type a bubble message…");
107	  cancelBtn.textContent = t("Cancel");
108	  sendBtn.textContent = t("Send");
109	  ball.title = t("Left-click: bubble · Right-click: settings · Drag to move");
110	}
111	
112	function shrinkToBall() {
113	  void win.setSize(new LogicalSize(WIN_SIZE, WIN_SIZE));
114	}
115	
116	/// Height delta between the menu window and the ball window.
117	const MENU_GROW = MENU_H - WIN_SIZE;
118	
119	async function showMenu() {
120	  if (!menu.hidden) return;
121	  input.value = "";
122	  selectedPreset = -1;
123	  paintPresets();
124	  syncSend();
125	
126	  const pos = await win.outerPosition();
127	  const sf = await win.scaleFactor();
128	  const mon = await currentMonitor();
129	  const work = mon?.workArea;
130	  const logicalX = pos.x / sf;
131	  const logicalY = pos.y / sf;
132	  const workLeft = work ? work.position.x / sf : logicalX;
133	  const workTop = work ? work.position.y / sf : logicalY;
134	  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
135	  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;
136	
137	  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
138	  // the bottom of the window and the menu sits above it. The window's Y
139	  // moves up by MENU_GROW so the ball's screen position is preserved.
140	  const openAbove = logicalY + MENU_H > workBottom;
141	  // Adjust X so the wider menu window stays on-screen.
142	  let newX = logicalX;
143	  if (newX + MENU_W > workRight) newX = workRight - MENU_W;
144	  if (newX < workLeft) newX = workLeft;
145	  let newY = logicalY;
146	  if (openAbove) newY = logicalY - MENU_GROW;
147	  // Clamp Y so the window never starts above the work area.
148	  if (newY < workTop) newY = workTop;
149	
150	  document.body.classList.toggle("menu-above", openAbove);
151	  if (Math.abs(newX - logicalX) > 0.5 || Math.abs(newY - logicalY) > 0.5) {
152	    void win.setPosition(new LogicalPosition(newX, newY));
153	  }
154	  // Resize FIRST, then reveal the menu, so the menu never appears clipped
155	  // inside the still-80×80 window for a frame.
156	  await win.setSize(new LogicalSize(MENU_W, MENU_H));
157	  menu.hidden = false;
158	  requestAnimationFrame(() => input.focus());
159	}
